def exactitude(vraies, predites):
    bonnes = sum(1 for v, p in zip(vraies, predites) if v == p)
    return round(bonnes / len(vraies), 3)

def eqm(vraies, predites):
    return round(sum((v - p) ** 2 for v, p in zip(vraies, predites)) / len(vraies), 3)

def ajuster(xs, ys):
    mx = sum(xs) / len(xs)
    my = sum(ys) / len(ys)
    a = sum((x - mx) * (y - my) for x, y in zip(xs, ys)) / sum((x - mx) ** 2 for x in xs)
    b = my - a * mx
    return round(a, 3), round(b, 3)

