def entrainer(xs, ys, pas, epoques):
    a, b = 0.0, 0.0
    n = len(xs)
    for _ in range(epoques):
        grad_a = 2 / n * sum(((a * x + b) - y) * x for x, y in zip(xs, ys))
        grad_b = 2 / n * sum(((a * x + b) - y) for x, y in zip(xs, ys))
        a = a - pas * grad_a
        b = b - pas * grad_b
    return round(a, 2), round(b, 2)
